let _cachedAllNodesDocs = null;
let _cachedFullMarkdown = null;

function normalizeSearchText(str = '') {
  return String(str || '')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .replace(/[^a-z0-9_.\s/-]+/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function extractBalancedJsLiteral(src, exportName, openChar, closeChar) {
  const marker = `export const ${exportName}`;
  const idx = src.indexOf(marker);
  if (idx === -1) {
    throw new Error(`No se encontró ${marker} en workflowNodesCatalog.ts`);
  }
  const eqIdx = src.indexOf('=', idx);
  const startIdx = src.indexOf(openChar, eqIdx);
  if (eqIdx === -1 || startIdx === -1) {
    throw new Error(`Inicio inválido para ${exportName}`);
  }

  let depth = 0;
  let quote = null;
  let escaped = false;
  let inLineComment = false;
  let inBlockComment = false;

  for (let i = startIdx; i < src.length; i++) {
    const ch = src[i];
    const next = src[i + 1];

    if (inLineComment) {
      if (ch === '\n') inLineComment = false;
      continue;
    }
    if (inBlockComment) {
      if (ch === '*' && next === '/') {
        inBlockComment = false;
        i += 1;
      }
      continue;
    }
    if (quote) {
      if (escaped) {
        escaped = false;
        continue;
      }
      if (ch === '\\') {
        escaped = true;
        continue;
      }
      if (ch === quote) {
        quote = null;
      }
      continue;
    }

    if (ch === '/' && next === '/') {
      inLineComment = true;
      i += 1;
      continue;
    }
    if (ch === '/' && next === '*') {
      inBlockComment = true;
      i += 1;
      continue;
    }
    if (ch === "'" || ch === '"' || ch === '`') {
      quote = ch;
      continue;
    }

    if (ch === openChar) {
      depth += 1;
    } else if (ch === closeChar) {
      depth -= 1;
      if (depth === 0) {
        return src.slice(startIdx, i + 1);
      }
    }
  }

  throw new Error(`Literal desbalanceado en ${exportName}`);
}

function loadRawCatalogAst() {
  const candidatePaths = [
    path.resolve(__dirname, '../../../client/src/components/SGSST/workflowNodesCatalog.ts'),
    path.resolve(process.cwd(), 'client/src/components/SGSST/workflowNodesCatalog.ts'),
    path.resolve(process.cwd(), '../client/src/components/SGSST/workflowNodesCatalog.ts'),
  ];

  for (const tsPath of candidatePaths) {
    try {
      if (!fs.existsSync(tsPath)) continue;
      const src = fs.readFileSync(tsPath, 'utf8');
      const arrayNames = [
        'TRIGGER_NODES',
        'EXTRACTOR_NODES',
        'AI_ENGINE_MODELS',
        'MEMORY_NODES',
        'INPUT_CONNECTOR_NODES',
        'SKILL_RULE_SUBAGENT_NODES',
        'HITO_APP_NODES',
        'OUTPUT_ACTION_NODES',
      ];
      const out = {};
      for (const name of arrayNames) {
        const lit = extractBalancedJsLiteral(src, name, '[', ']');
        out[name] = vm.runInNewContext(`(${lit})`, Object.create(null), { timeout: 800 });
      }
      const metaLit = extractBalancedJsLiteral(src, 'MODULE_METADATA_MAP', '{', '}');
      out.MODULE_METADATA_MAP = vm.runInNewContext(`(${metaLit})`, Object.create(null), {
        timeout: 1200,
      });
      return out;
    } catch (_) {}
  }

  // Respaldo determinista embebido para producción Docker (/app/api)
  if (
    EMBEDDED_CATALOG_GZIP_B64 &&
    EMBEDDED_CATALOG_GZIP_B64 !== '__EMBEDDED_CATALOG_GZIP_B64__'
  ) {
    const jsonStr = zlib
      .gunzipSync(Buffer.from(EMBEDDED_CATALOG_GZIP_B64, 'base64'))
      .toString('utf8');
    return JSON.parse(jsonStr);
  }

  return {
    TRIGGER_NODES: [],
    EXTRACTOR_NODES: [],
    AI_ENGINE_MODELS: [],
    MEMORY_NODES: [],
    INPUT_CONNECTOR_NODES: [],
    SKILL_RULE_SUBAGENT_NODES: [],
    HITO_APP_NODES: [],
    OUTPUT_ACTION_NODES: [],
    MODULE_METADATA_MAP: {},
  };
}

function doesNodeRequireAntigravityCheck(nodeId = '', familyId = '', rawNode = {}) {
  const id = String(nodeId || '').toLowerCase();
  const engine = String(rawNode?.engine || '').toLowerCase();
  const nodeType = String(rawNode?.nodeType || '').toLowerCase();

  if (
    id === 'trigger_antigravity' ||
    id === 'trigger_antigravity_cloud' ||
    id === 'extract_pc_folder' ||
    id === 'extract_web_scraping_agy' ||
    id === 'tool_web_scraping_agy' ||
    id === 'google_antigravity' ||
    id === 'google_antigravity_cloud' ||
    id === 'antigravity_mcp_engine' ||
    id === 'antigravity_cloud_mcp_engine' ||
    id === 'antigravity_local_report' ||
    id === 'antigravity_cloud_report' ||
    id === 'wappy_rag_documental' ||
    id === 'notebooklm' ||
    id === 'google_flow' ||
    id === 'scraper_node_antigravity' ||
    id === 'subagent_scraper_agy' ||
    id === 'agent_root'
  ) {
    return true;
  }
  if (
    id.includes('scraper_agy') ||
    id.includes('antigravity') ||
    engine === 'antigravity' ||
    engine === 'antigravity_cloud' ||
    nodeType === 'web_scraper'
  ) {
    return true;
  }
  if (familyId === 'ai_models' && id.includes('antigravity')) {
    return true;
  }
  return false;
}

function resolveMetadataForNode(rawId, docId, sgsstAppId, metaMap = {}) {
  if (metaMap[docId]) return metaMap[docId];
  if (metaMap[rawId]) return metaMap[rawId];
  const stripped = String(rawId || '').replace(
    /^(trigger_|extractor_|ext_|hito_src_|hito_|out_|tool_inputs_|tool_hitos_|sub_memory_|custom_)/,
    '',
  );
  if (metaMap[stripped]) return metaMap[stripped];
  if (sgsstAppId && metaMap[sgsstAppId]) return metaMap[sgsstAppId];
  if (rawId === 'acpm_task' && metaMap.hito7_acpm) return metaMap.hito7_acpm;
  if (rawId === 'somos_sst_empresa' && metaMap.wappy_memory_company) {
    return metaMap.wappy_memory_company;
  }
  return null;
}

function inferNormativeBasis(entry) {
  if (SPECIAL_NODE_OVERRIDES[entry.catalogId]?.normativeBasis) {
    return SPECIAL_NODE_OVERRIDES[entry.catalogId].normativeBasis;
  }
  if (SPECIAL_NODE_OVERRIDES[entry.id]?.normativeBasis) {
    return SPECIAL_NODE_OVERRIDES[entry.id].normativeBasis;
  }
  if (entry.hitoId && HITO_NORMATIVE_MAP[entry.hitoId]) {
    return HITO_NORMATIVE_MAP[entry.hitoId];
  }
  const hay = normalizeSearchText(`${entry.id} ${entry.label} ${entry.description} ${entry.toolHint}`);
  if (hay.includes('pesv') || hay.includes('vial') || hay.includes('simit')) {
    return 'Resolución 20223040040595 de 2022 (Plan Estratégico de Seguridad Vial — PESV) e ISO 39001';
  }
  if (hay.includes('quimic') || hay.includes('sga') || hay.includes('pubchem')) {
    return 'Decreto 1496 de 2018 (Sistema Globalmente Armonizado — SGA), Ley 55 de 1993 y NTC 1692';
  }
  if (hay.includes('gtc') || hay.includes('ipevar') || hay.includes('peligro')) {
    return 'Guía Técnica Colombiana GTC-45 (2.ª Actualización) y Decreto 1072 de 2015 Art. 2.2.4.6.15';
  }
  if (hay.includes('psicosocial') || hay.includes('convivencia') || hay.includes('mental')) {
    return 'Resolución 2764 de 2022 (Batería de Riesgo Psicosocial), Ley 1010 de 2006 y Resolución 3461 de 2025';
  }
  if (hay.includes('medico') || hay.includes('emo') || hay.includes('medlineplus') || hay.includes('rethus')) {
    return 'Resolución 1843 de 2025 / Resolución 2346 de 2007 (Evaluaciones Médicas Ocupacionales), Decreto 1427 de 2022 y Ley 23 de 1981 (Reserva de Historia Clínica)';
  }
  if (hay.includes('alturas') || hay.includes('confinados') || hay.includes('tareas criticas')) {
    return 'Resolución 4272 de 2021 (Trabajo Seguro en Alturas) y Resolución 0491 de 2020 (Espacios Confinados)';
  }
  if (hay.includes('atel') || hay.includes('accidente') || hay.includes('furat')) {
    return 'Resolución 1401 de 2007 (Investigación de Incidentes y Accidentes de Trabajo) y NTC 3701';
  }
  if (hay.includes('0312') || hay.includes('auditor')) {
    return 'Resolución 0312 de 2019 (Estándares Mínimos del SG-SST) y Decreto 1072 de 2015 Art. 2.2.4.6.29';
  }
  return 'Decreto 1072 de 2015 (Libro 2, Parte 2, Título 4, Capítulo 6 — SG-SST) y Resolución 0312 de 2019';
}

